public str getName()
{
    return fieldPName(EcoResProductCategory, Category);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::Int64);
    EcoResProductCategory ecoResProductCategory;
    while select Category from ecoResProductCategory
        group by Category
    {
        ret.add(ecoResProductCategory.Category);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(EcoResProductCategory, Category));
    qbr.value(queryValue(_value));
}
